    const h = await this.phoneHash(phone), c = this.one('SELECT * FROM codes WHERE phone = ?', h), now = Date.now();
    if (!c || c.exp < now) return json({ error: 'expired' }, 400);
    if (c.tries >= 5) return json({ error: 'too-many' }, 429);
