  // ---- Your profile (name, @username, privacy) ----
  meView(u) { return { id: u.id, name: u.name || '', username: u.username || '', nameAt: u.name_at || 0, usernameAt: u.username_at || 0, official: !!u.official, country: u.country || '' }; }
