    const r = this.one('SELECT COUNT(*) AS c, MAX(n) AS n, MIN(uid) AS u, MAX(uid) AS u2 FROM media WHERE id = ?', id);
    return !!(r && r.c && r.c === r.n && r.u === uid && r.u2 === uid);
